with "CL_BATCH_HEADER4" as (
select "CL_BATCH_HEADER"."BATCH_ID", "CL_BATCH_HEADER"."PROV_CODE", "CL_BATCH_HEADER"."RCV_DATE", "CL_BATCH_HEADER"."PERIOD", "CL_BATCH_HEADER"."BILL_PRESENT_AMT", "CL_BATCH_HEADER"."BILL_DISC_AMT", "CL_BATCH_HEADER"."BILL_DEDUCT_AMT", "CL_BATCH_HEADER"."CRT_DATE", "CL_BATCH_HEADER"."NOTES", "CL_BATCH_HEADER"."UN_HOLD_DATE", "CL_BATCH_HEADER"."VAT_AMT", "CL_BATCH_HEADER"."HOLD_REASON", "SY_STATUS_BATCH_HEADER"."EDESC" "BATCH_STATUS_DESC", "SYS_SUBMIS_TYPE"."EDESC" "CLM_SUBMISSION_TYPE", "CL_BATCH_HEADER"."TPA"
 from ("CSR"."CL_BATCH_HEADER" "CL_BATCH_HEADER" INNER JOIN "CSR"."SY_STATUS_BATCH_HEADER" "SY_STATUS_BATCH_HEADER" on "CL_BATCH_HEADER"."STATUS"="SY_STATUS_BATCH_HEADER"."SYS_CODE") LEFT OUTER JOIN "CSR"."SY_SYS_CODE" "SYS_SUBMIS_TYPE" on "CL_BATCH_HEADER"."CLM_SUBMIS_TYPE"="SYS_SUBMIS_TYPE"."SYS_CODE" and 'CLM_SUBMISSION_TYPE'="SYS_SUBMIS_TYPE"."SYS_TYPE"), "PV_PROVIDER5" as (
select "PV_PROVIDER"."PROV_CODE", "PV_PROVIDER"."PROV_NAME", "PV_PROVIDER"."CORR_DIST_CODE", "PV_PROVIDER"."RELATIONS"
 from (((((("CSR"."PV_PROVIDER" "PV_PROVIDER" INNER JOIN "CSR"."DC_DISTRICT" "DC_DISTRICT" on "PV_PROVIDER"."CORR_DIST_CODE"="DC_DISTRICT"."DIST_CODE") LEFT OUTER JOIN "CSR"."SY_PROVIDER_LEVEL" "SY_PROVIDER_LEVEL1" on "PV_PROVIDER"."PROV_LEVEL"="SY_PROVIDER_LEVEL1"."SYS_CODE") LEFT OUTER JOIN "CSR"."SY_PRACTICE_TYPE" "SY_PRACTICE_TYPE" on "PV_PROVIDER"."PRACTICE_TYPE"="SY_PRACTICE_TYPE"."SYS_CODE") LEFT OUTER JOIN "CSR"."PV_PROV_LVL_MVMNT" on "PV_PROVIDER"."PROV_CODE"="PV_PROV_LVL_MVMNT"."PROV_CODE") LEFT OUTER JOIN "CSR"."SY_PROVIDER_LEVEL" "SY_PROVIDER_LEVEL2" on "PV_PROV_LVL_MVMNT"."PROV_LEVEL"="SY_PROVIDER_LEVEL2"."SYS_CODE") LEFT OUTER JOIN "CSR"."SY_SYS_CODE" "VRS" on "PV_PROVIDER"."VAT_REG_STATUS"=trim(both
 from "VRS"."SYS_CODE") and 'VAT_REG_STATUS'=trim(both
 from "VRS"."SYS_TYPE")) LEFT OUTER JOIN "CSR"."SY_SYS_CODE" "CTC" on "PV_PROVIDER"."CTRY_CODE"=trim(both
 from "CTC"."SYS_CODE") and 'COUNTRY_CODE'=trim(both
 from "CTC"."SYS_TYPE")
 where "PV_PROV_LVL_MVMNT"."END_DATE" is null and "PV_PROVIDER"."PRACTICE_TYPE"<>280), "SY_PROVIDER_LOCATION" as (
select "DC_DISTRICT"."DIST_CODE", "DC_DISTRICT"."EDESC" "TOWN", "DC_DISTRICT"."AREA_CODE"
 from "CSR"."DC_DISTRICT" "DC_DISTRICT"), "SY_PROVIDER_LOCATION6" as (
select "SY_PROVIDER_LOCATION"."DIST_CODE" "DIST_CODE", case  when "SY_PROVIDER_LOCATION"."AREA_CODE"='W' then 'a. Western Region' when "SY_PROVIDER_LOCATION"."AREA_CODE"='C' then 'b. Central Region' when "SY_PROVIDER_LOCATION"."AREA_CODE"='E' then 'c. Eastern Region' when "SY_PROVIDER_LOCATION"."AREA_CODE"='N' then 'd. Northern Region' when "SY_PROVIDER_LOCATION"."AREA_CODE"='S' then 'e. Southern Region' else 'f. Overseas' end  "REGION"
 from "SY_PROVIDER_LOCATION") 
select "CL_BATCH_HEADER4"."BATCH_ID" "Batch_ID", "CL_BATCH_HEADER4"."PERIOD" "Batch_Period", substr("CL_BATCH_HEADER4"."PERIOD", 1, 4) "Batch_Year", "CL_BATCH_HEADER4"."BATCH_STATUS_DESC" "Batch_Status", sum((nvl("CL_BATCH_HEADER4"."BILL_PRESENT_AMT", 0) - nvl("CL_BATCH_HEADER4"."BILL_DISC_AMT", 0)) - nvl("CL_BATCH_HEADER4"."BILL_DEDUCT_AMT", 0)) "PROV_Netbilled", sum("CL_BATCH_HEADER4"."VAT_AMT") "VAT_AMT", "CL_BATCH_HEADER4"."NOTES" "Batch_Notes", "CL_BATCH_HEADER4"."CLM_SUBMISSION_TYPE" "Claim_Submission_Type", "CL_BATCH_HEADER4"."HOLD_REASON" "Hold_Reason", "CL_BATCH_HEADER4"."RCV_DATE" "Batch_Received_Date", "CL_BATCH_HEADER4"."UN_HOLD_DATE" "UnholdDate", trim(both
 from "PV_PROVIDER5"."PROV_CODE") "Provider_Code", "PV_PROVIDER5"."PROV_NAME" "Provider_Name", "SY_PROVIDER_LOCATION6"."REGION" "Provider_Region", "PV_PROVIDER5"."RELATIONS" "Relations", "CL_BATCH_HEADER4"."CRT_DATE" "Create_Date", sum(((nvl("CL_BATCH_HEADER4"."BILL_PRESENT_AMT", 0) - nvl("CL_BATCH_HEADER4"."BILL_DISC_AMT", 0)) - nvl("CL_BATCH_HEADER4"."BILL_DEDUCT_AMT", 0)))+sum("CL_BATCH_HEADER4"."VAT_AMT") "PROV_NB___VAT", "CL_BATCH_HEADER4"."TPA" "TPA_Batch"
 from ("CL_BATCH_HEADER4" INNER JOIN "PV_PROVIDER5" on "CL_BATCH_HEADER4"."PROV_CODE"="PV_PROVIDER5"."PROV_CODE") LEFT OUTER JOIN "SY_PROVIDER_LOCATION6" on "PV_PROVIDER5"."CORR_DIST_CODE"="SY_PROVIDER_LOCATION6"."DIST_CODE"
 where "CL_BATCH_HEADER4"."RCV_DATE" between CAST( ( :PQ1 ) AS TIMESTAMP ) and CAST( ( :PQ2 ) AS TIMESTAMP )
 group by "CL_BATCH_HEADER4"."BATCH_ID", "CL_BATCH_HEADER4"."PERIOD", substr("CL_BATCH_HEADER4"."PERIOD", 1, 4), "CL_BATCH_HEADER4"."BATCH_STATUS_DESC", "CL_BATCH_HEADER4"."NOTES", "CL_BATCH_HEADER4"."CLM_SUBMISSION_TYPE", "CL_BATCH_HEADER4"."HOLD_REASON", "CL_BATCH_HEADER4"."RCV_DATE", "CL_BATCH_HEADER4"."UN_HOLD_DATE", trim(both
 from "PV_PROVIDER5"."PROV_CODE"), "PV_PROVIDER5"."PROV_NAME", "SY_PROVIDER_LOCATION6"."REGION", "PV_PROVIDER5"."RELATIONS", "CL_BATCH_HEADER4"."CRT_DATE", "CL_BATCH_HEADER4"."TPA"
